CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;


DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260802134057_InitialCreate') THEN
    CREATE TABLE "Shifts" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Name" character varying(100) NOT NULL,
        "StartTime" interval NOT NULL,
        "EndTime" interval NOT NULL,
        "Description" character varying(255),
        CONSTRAINT "PK_Shifts" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260802134057_InitialCreate') THEN
    CREATE TABLE "Users" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "FullName" character varying(100) NOT NULL,
        "Username" character varying(50) NOT NULL,
        "Password" character varying(100) NOT NULL,
        "Role" character varying(20) NOT NULL,
        "Phone" character varying(20),
        "Email" character varying(200),
        "Address" character varying(255),
        "SalaryPerShift" numeric NOT NULL,
        "BaseSalary" numeric NOT NULL,
        "IsActive" boolean NOT NULL,
        "CreatedAt" timestamp without time zone NOT NULL,
        CONSTRAINT "PK_Users" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260802134057_InitialCreate') THEN
    CREATE TABLE "Attendances" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "UserId" integer NOT NULL,
        "ShiftId" integer NOT NULL,
        "Date" timestamp without time zone NOT NULL,
        "CheckIn" timestamp without time zone,
        "CheckOut" timestamp without time zone,
        "OvertimeHours" numeric NOT NULL,
        "Status" character varying(50) NOT NULL,
        "Notes" character varying(500),
        "CreatedAt" timestamp without time zone NOT NULL,
        "UpdatedAt" timestamp without time zone,
        CONSTRAINT "PK_Attendances" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Attendances_Shifts_ShiftId" FOREIGN KEY ("ShiftId") REFERENCES "Shifts" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_Attendances_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

